// Mirrors src/csv.js of the CLI example: required-column checks,
// per-row validation, slugified job names, optional row limit.
// The -r<row> suffix in the job name is what lets the receiver workflow map
// each webhook event back to its CSV row.
const REQUIRED = ['first_name','product_name','product_tagline','product_image','discount_label','coupon_code','cta_url'];
const cfg = $('Campaign Config').first().json;
const rows = $input.all().map((i) => i.json);
if (rows.length === 0) throw new Error('CSV contains no data rows');

const missing = REQUIRED.filter((c) => !(c in rows[0]));
if (missing.length) {
  throw new Error(`CSV is missing required column(s): ${missing.join(', ')}. Expected header: ${REQUIRED.join(',')}`);
}

const slugify = (v) => String(v).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '') || 'row';
// note: the Code sandbox has no URL global - keep this a regex
const isHttpUrl = (v) => /^https?:\/\//i.test(String(v).trim());

const items = [];
const rowErrors = [];
rows.forEach((record, index) => {
  const row = index + 1; // 1-based CSV data row (header excluded)
  const problems = [];
  for (const c of REQUIRED) if (!record[c]) problems.push(`"${c}" is empty`);
  if (record.product_image && !isHttpUrl(record.product_image)) problems.push('"product_image" must be an http(s) URL');
  if (problems.length) { rowErrors.push({ row, error: problems.join('; ') }); return; }
  items.push({
    row,
    name: `offer-${slugify(record.first_name)}-r${row}`,
    variables: {
      firstName: record.first_name,
      productName: record.product_name,
      productMeta: record.product_tagline,
      productImage: record.product_image,
      discountLabel: record.discount_label,
      couponCode: record.coupon_code,
      ctaUrl: record.cta_url,
    },
  });
});

if (items.length === 0) throw new Error('No valid rows in the CSV - nothing to render. Reasons: ' + JSON.stringify(rowErrors.slice(0, 5)));
const limit = Number(cfg.rowLimit) || 0;
const limited = limit > 0 ? items.slice(0, limit) : items;
// rowErrors ride on the first item so the summary can report skipped rows
return limited.map((it, i) => ({ json: i === 0 ? { ...it, rowErrors } : it }));

// Per-row validation report + total credit estimate. No credits spent.
const items = $('Build bulk items').all().map((i) => i.json);
const results = $input.all().map((i) => i.json);
let creditsRequired = 0;
let invalid = 0;
const rows = results.map((r, i) => {
  const item = items[i] || {};
  if (r.error || r.valid === false) {
    invalid += 1;
    const message = typeof r.error === 'string' ? r.error : (r.error && r.error.message) || r.message || 'invalid';
    return { csv_row: item.row, name: item.name, valid: false, error: message };
  }
  creditsRequired += r.creditsRequired || 0;
  return { csv_row: item.row, name: item.name, valid: true, credits: r.creditsRequired, layoutWarnings: (r.warnings || []).length };
});
return [{ json: {
  dryRun: true,
  videos: results.length - invalid,
  invalidRows: invalid,
  creditsRequired,
  note: 'No credits were spent. Set dryRun=false in Campaign Config to render.',
  rows,
} }];

// One envelope per batch. webhookUrl makes Zvid POST a render.completed /
// render.failed event to the receiver workflow for every job in the batch.
const cfg = $('Campaign Config').first().json;
const receiver = String(cfg.webhookReceiverUrl || '');
if (!/^https?:\/\//i.test(receiver) || receiver.includes('YOUR-N8N-HOST')) {
  throw new Error('Set webhookReceiverUrl in Campaign Config to your receiver workflow\'s production webhook URL (publicly reachable).');
}
const items = $input.all().map((i) => i.json);
return [{ json: {
  request: {
    payload: $('Fetch template.json').first().json,
    variables: $('Fetch campaign.json').first().json,
    items: items.map(({ variables, name }) => ({ variables, name })),
    name: cfg.batchName,
    webhookUrl: receiver,
  },
} }];

// One 202 response per batch arrives on the loop's done-output, in order.
// Map queued jobs back to CSV rows via the batch-relative jobs[].index.
const cfg = $('Campaign Config').first().json;
const batchSize = Math.max(1, Number(cfg.batchSize) || 100);
const allItems = $('Build bulk items').all().map((i) => i.json);
const submits = $input.all().map((i) => i.json);

const queued = [];
const rejected = [];
submits.forEach((submit, b) => {
  const batch = allItems.slice(b * batchSize, (b + 1) * batchSize);
  for (const job of submit.jobs || []) {
    const item = batch[job.index] || {};
    queued.push({ jobId: job.jobId, csv_row: item.row, name: item.name });
  }
  for (const e of submit.errors || submit.itemErrors || []) {
    const idx = e.item != null ? e.item : e.index;
    const item = typeof idx === 'number' ? batch[idx] : undefined;
    const details = (e.errors || e.details || []).map((d) => `${d.field}: ${d.message}`).join('; ');
    rejected.push({ csv_row: item ? item.row : null, name: item ? item.name : `item-${idx}`, error: details || e.error || e.message || 'invalid' });
  }
});

return [{ json: {
  submitted: queued.length,
  rejected,
  rowErrors: $('Build bulk items').first().json.rowErrors || [],
  creditsReserved: submits.reduce((a, s) => a + (s.creditsReserved || 0), 0),
  bulkIds: submits.map((s) => s.bulkId),
  receiver: cfg.webhookReceiverUrl,
  note: 'Done - no polling. Zvid will POST render.completed / render.failed to the receiver for every job. Credits for failed jobs are refunded automatically.',
  queued,
} }];
